  /**
   * read(CharBuffer) on a sequence backed by a single non-empty reader should
   * copy one character into a writable target buffer and report one char read.
   */
  @Test(timeout = 4000)
  public void readIntoWritableCharBufferReturnsCharsCopied()  throws Throwable  {
      LinkedHashSet<StringReader> readers = new LinkedHashSet<StringReader>();
      char[] targetBacking = new char[1];
      CharBuffer target = CharBuffer.wrap(targetBacking);
      StringReader reader = new StringReader("org.apache.commons.io.filefilter.AgeFileFilter");
      readers.add(reader);
      SequenceReader sequenceReader = new SequenceReader(readers);

      int charsRead = sequenceReader.read(target);

      // The first character of the source string is copied into the buffer's backing array.
      assertArrayEquals(new char[] {'o'}, targetBacking);
      assertEquals(1, charsRead);
  }

