  @Test(timeout = 4000)
  public void readIntoReadOnlyCharBufferThrows()  throws Throwable  {
      LinkedHashSet<StringReader> readers = new LinkedHashSet<StringReader>();
      StringReader reader = new StringReader("org.apache.commons.io.filefilter.AgeFileFilter");
      readers.add(reader);
      SequenceReader sequenceReader = new SequenceReader(readers);
      sequenceReader.read();
      // Buffers wrapping a CharSequence are read-only.
      CharBuffer readOnlyTarget = CharBuffer.wrap((CharSequence) "org.apache.commons.io.filefilter.AgeFileFilter");

